    12,
) ?>" required></label></div><label class="block text-sm font-medium">বিশেষ অনুরোধ<textarea class="w-full rounded-lg border border-stone-300 bg-white p-3 text-sm text-ink" name="notes" maxlength="2000" rows="2"></textarea></label><button class="btn-dark inline-flex items-center justify-center rounded-full px-6 py-3 text-sm font-semibold text-white transition disabled:opacity-40 bg-ink hover:bg-stone-700">বুকিংয়ের অনুরোধ পাঠান</button></form></div></section>
